"""Collects the completion token count of every generation call in a run.

Generation happens through several paths (synchronous and Gemini batch), so the
counts are accumulated here instead of being threaded through every return value.
"""

import threading

_lock = threading.Lock()
_completion_tokens: list[int] = []


def record_completion_tokens(*counts: int | None) -> None:
    """Record the tokens generated by a single call, thinking tokens included.

    Several counts are summed for APIs that report thinking tokens separately
    from the visible response (Gemini). Missing counts are treated as zero, but
    a call that reports no usage at all is not recorded.
    """
    if all(count is None for count in counts):
        return
    with _lock:
        _completion_tokens.append(sum(int(count or 0) for count in counts))


def get_completion_tokens() -> list[int]:
    """Return the completion token counts recorded so far."""
    with _lock:
        return list(_completion_tokens)
